#!/usr/bin/env python3
"""Compute deterministic ground truth for CSX-248_Q1."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Callable


TASK_ID = "CSX-248_Q1"
EVENT_ID = "CSX-248"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
TARGET_FAMILY = "northern_central_europe_heat_dry_onset_index"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_002_Locked_event_anchor_2018_Northern_and_Central_Europe_heatwave-drought-wildfire-low-river-f.json",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
]


def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def compact_size(value: dict) -> int:
    return len(json.dumps(value, ensure_ascii=True, separators=(",", ":")))


def longest_run(indices: list[int], predicate: Callable[[int], bool]) -> tuple[int, int | None, int | None]:
    best_len = 0
    best_start: int | None = None
    best_end: int | None = None
    current_len = 0
    current_start: int | None = None

    for idx in indices:
        if predicate(idx):
            if current_len == 0:
                current_start = idx
            current_len += 1
            if current_len > best_len:
                best_len = current_len
                best_start = current_start
                best_end = idx
        else:
            current_len = 0
            current_start = None

    return best_len, best_start, best_end


def capped(value: float) -> float:
    return min(value, 1.0)


def build_result() -> dict:
    event_meta = read_json(SOURCE_FILES[0])
    anchor = read_json(SOURCE_FILES[1])
    weather = read_json(SOURCE_FILES[2])
    era5_stats = read_json(SOURCE_FILES[3])["stats"]

    daily = weather["daily"]
    dates = daily["time"]
    tmax = daily["temperature_2m_max"]
    tmin = daily["temperature_2m_min"]
    precip = daily["precipitation_sum"]

    start = anchor["temporal_window"]["start_date"]
    end = dates[-1]
    indices = [idx for idx, date in enumerate(dates) if start <= date <= end]

    heat_load = sum(max(float(tmax[idx]) - 25.0, 0.0) for idx in indices)
    hot_spell = longest_run(indices, lambda idx: float(tmax[idx]) >= 25.0)
    warm_night = longest_run(indices, lambda idx: float(tmin[idx]) >= 16.0)
    dry_run = longest_run(indices, lambda idx: float(precip[idx]) <= 1.0)
    hot_dry = longest_run(
        indices,
        lambda idx: float(tmax[idx]) >= 25.0 and float(precip[idx]) <= 1.0,
    )

    local_precip_sum = sum(float(precip[idx]) for idx in indices)
    regional_precip_mean = float(era5_stats["precipitation_sum_mm_mean"])
    local_regional_precip_ratio = local_precip_sum / regional_precip_mean

    components = {
        "heat_load": capped(heat_load / 35.0),
        "hot_spell": capped(hot_spell[0] / 9.0),
        "warm_night": capped(warm_night[0] / 7.0),
        "dry_run": capped(dry_run[0] / 12.0),
        "hot_dry": capped(hot_dry[0] / 5.0),
        "precip_deficit": max(0.0, min(1.0, 1.0 - local_regional_precip_ratio)),
    }
    onset_score = 100.0 * (
        0.25 * components["heat_load"]
        + 0.15 * components["hot_spell"]
        + 0.15 * components["warm_night"]
        + 0.20 * components["dry_run"]
        + 0.20 * components["hot_dry"]
        + 0.05 * components["precip_deficit"]
    )
    answer = "compound_onset_gate_met" if onset_score >= 90.0 else "compound_onset_gate_not_met"

    primary_gt = {
        "answer": answer,
        "heat_load_cday": round(heat_load, 1),
        "hot_spell_days": hot_spell[0],
        "warm_night_run_days": warm_night[0],
        "dry_run_days": dry_run[0],
        "hot_dry_overlap_days": hot_dry[0],
        "local_regional_precip_ratio": round(local_regional_precip_ratio, 3),
        "onset_score": round(onset_score, 2),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "primary_gt": primary_gt,
        "event": {
            "event_id": EVENT_ID,
            "event_name": event_meta["event_name"],
            "event_window": (
                f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}"
            ),
            "weather_slice": f"{start} to {end}",
        },
        "calculation": {
            "inputs": {
                "weather_days": len(indices),
                "local_precip_sum_mm": round(local_precip_sum, 1),
                "regional_precip_mean_mm": round(regional_precip_mean, 6),
            },
            "runs": {
                "hot_spell_ge_25c": {
                    "days": hot_spell[0],
                    "start": dates[hot_spell[1]],
                    "end": dates[hot_spell[2]],
                },
                "warm_night_ge_16c": {
                    "days": warm_night[0],
                    "start": dates[warm_night[1]],
                    "end": dates[warm_night[2]],
                },
                "dry_run_le_1mm": {
                    "days": dry_run[0],
                    "start": dates[dry_run[1]],
                    "end": dates[dry_run[2]],
                },
                "hot_dry_overlap": {
                    "days": hot_dry[0],
                    "start": dates[hot_dry[1]],
                    "end": dates[hot_dry[2]],
                },
            },
            "components": {key: round(value, 6) for key, value in components.items()},
            "formula": (
                "100*(0.25*min(heat_load/35,1)+0.15*min(hot_spell/9,1)+"
                "0.15*min(warm_night/7,1)+0.20*min(dry_run/12,1)+"
                "0.20*min(hot_dry/5,1)+0.05*max(0,min(1,1-local_regional_precip_ratio)))"
            ),
            "threshold": {"onset_score_gte_90": onset_score >= 90.0},
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Weather slice",
                    "points": 4,
                    "description": "Filters the Open-Meteo daily series to 2018-05-01 through 2018-06-15.",
                    "partial_credit": "Award 2-3 points for using the correct product with a minor date-window or indexing error.",
                },
                {
                    "name": "Heat load",
                    "points": 4,
                    "description": "Computes Tmax exceedance above 25 C and rounds it to 35.7 C-days.",
                    "partial_credit": "Award 2-3 points for the right formula with a minor summation or rounding error.",
                },
                {
                    "name": "Heat persistence",
                    "points": 3,
                    "description": "Computes the 9-day hot spell and 7-day warm-night run.",
                    "partial_credit": "Award 1-2 points if one of the two run lengths is correct.",
                },
                {
                    "name": "Dry persistence",
                    "points": 3,
                    "description": "Computes the 12-day dry run and 5-day hot-dry overlap run.",
                    "partial_credit": "Award 1-2 points if one of the two dry or overlap runs is correct.",
                },
                {
                    "name": "Precipitation ratio",
                    "points": 3,
                    "description": "Computes the local precipitation sum over the ERA5-Land regional mean and rounds to 0.657.",
                    "partial_credit": "Award 1-2 points for the correct sources with a denominator, sum, or rounding mistake.",
                },
                {
                    "name": "Index formula",
                    "points": 3,
                    "description": "Applies the weighted formula, rounds the score to 96.71, and returns the compact JSON fields.",
                    "partial_credit": "Award 1-2 points for a mostly correct weighted formula or final label with one component error.",
                },
            ],
        },
        "quality_checks": {
            "primary_gt_top_level_keys": len(primary_gt),
            "primary_gt_compact_bytes": compact_size(primary_gt),
            "rubric_points": 20,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    result = build_result()
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(result, indent=2, sort_keys=True, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
